00079         class InstructionSet_Internal
00080         {
00081         public:
00082             InstructionSet_Internal()
00083                 : nIds_{ 0 },
00084                 nExIds_{ 0 },
00085                 isIntel_{ false },
00086                 isAMD_{ false },
00087                 f_1_ECX_{ 0 },
00088                 f_1_EDX_{ 0 },
00089                 f_7_EBX_{ 0 },
00090                 f_7_ECX_{ 0 },
00091                 f_81_ECX_{ 0 },
00092                 f_81_EDX_{ 0 },
00093                 data_{},
00094                 extdata_{}
00095             {
00096                 //int cpuInfo[4] = {-1};
00097                 std::array<int, 4> cpui;
00098 
00099                 // Calling __cpuid with 0x0 as the function_id argument
00100                 // gets the number of the highest valid function ID.
00101                 __cpuid(cpui.data(), 0);
00102                 nIds_ = cpui[0];
00103 
00104                 for (int i = 0; i <= nIds_; ++i)
00105                 {
00106                     __cpuidex(cpui.data(), i, 0);
00107                     data_.push_back(cpui);
00108                 }
00109 
00110                 // Capture vendor string
00111                 char vendor[0x20];
00112                 memset(vendor, 0, sizeof(vendor));
00113                 *reinterpret_cast<int*>(vendor) = data_[0][1];
00114                 *reinterpret_cast<int*>(vendor + 4) = data_[0][3];
00115                 *reinterpret_cast<int*>(vendor + 8) = data_[0][2];
00116                 vendor_ = vendor;
00117                 if (vendor_ == "GenuineIntel")
00118                 {
00119                     isIntel_ = true;
00120                 }
00121                 else if (vendor_ == "AuthenticAMD")
00122                 {
00123                     isAMD_ = true;
00124                 }
00125 
00126                 // load bitset with flags for function 0x00000001
00127                 if (nIds_ >= 1)
00128                 {
00129                     f_1_ECX_ = data_[1][2];
00130                     f_1_EDX_ = data_[1][3];
00131                 }
00132 
00133                 // load bitset with flags for function 0x00000007
00134                 if (nIds_ >= 7)
00135                 {
00136                     f_7_EBX_ = data_[7][1];
00137                     f_7_ECX_ = data_[7][2];
00138                 }
00139 
00140                 // Calling __cpuid with 0x80000000 as the function_id argument
00141                 // gets the number of the highest valid extended ID.
00142                 __cpuid(cpui.data(), 0x80000000);
00143                 nExIds_ = cpui[0];
00144 
00145                 char brand[0x40];
00146                 memset(brand, 0, sizeof(brand));
00147 
00148                 for (int i = 0x80000000; i <= nExIds_; ++i)
00149                 {
00150                     __cpuidex(cpui.data(), i, 0);
00151                     extdata_.push_back(cpui);
00152                 }
00153 
00154                 // load bitset with flags for function 0x80000001
00155                 if (nExIds_ >= 0x80000001)
00156                 {
00157                     f_81_ECX_ = extdata_[1][2];
00158                     f_81_EDX_ = extdata_[1][3];
00159                 }
00160 
00161                 // Interpret CPU brand string if reported
00162                 if (nExIds_ >= 0x80000004)
00163                 {
00164                     memcpy(brand, extdata_[2].data(), sizeof(cpui));
00165                     memcpy(brand + 16, extdata_[3].data(), sizeof(cpui));
00166                     memcpy(brand + 32, extdata_[4].data(), sizeof(cpui));
00167                     brand_ = brand;
00168                 }
00169             };
00170 
00171             int nIds_;
00172             int nExIds_;
00173             std::string vendor_;
00174             std::string brand_;
00175             bool isIntel_;
00176             bool isAMD_;
00177             std::bitset<32> f_1_ECX_;
00178             std::bitset<32> f_1_EDX_;
00179             std::bitset<32> f_7_EBX_;
00180             std::bitset<32> f_7_ECX_;
00181             std::bitset<32> f_81_ECX_;
00182             std::bitset<32> f_81_EDX_;
00183             std::vector<std::array<int, 4>> data_;
00184             std::vector<std::array<int, 4>> extdata_;
00185         };
